def to_schema(self):
    from dataclasses import replace

    return super(StructureOverlay, replace(
        self,
        aliases={} if self.aliases is Omitted() else self.aliases,
        alias_style=() if self.alias_style is Omitted() else self.alias_style,
    )).to_schema()

def _merge_aliases(self, old, new):
    return {**old, **new}
